export type Rgb = readonly [number, number, number]

export type Palette = {
  dark: boolean
  base: Rgb
  card: Rgb
  code: Rgb
  line: Rgb
  text: Rgb
  muted: Rgb
  faint: Rgb
  blue: Rgb
  green: Rgb
  orange: Rgb
  red: Rgb
  purple: Rgb
  teal: Rgb
  yellow: Rgb
  pink: Rgb
  selected: Rgb
  key: Rgb
  hero: readonly Rgb[]
  heroText: Rgb
  cat: Rgb
}

export const DARK: Palette = {
  dark: true,
  base: [13, 17, 23],
  card: [21, 27, 35],
  code: [17, 19, 23],
  line: [61, 68, 77],
